import{_ as t,c as a,o,ag as r}from"./chunks/framework.DZ_cNctr.js";const f=JSON.parse('{"title":"Supported Formats","description":"Every format the viewer opens: OME-Zarr, OME-TIFF, CZI, Phenix and Yokogawa plates, and slides from Aperio, Hamamatsu, Leica, Philips, 3DHISTECH, Akoya, DICOM.","frontmatter":{"title":"Supported Formats","description":"Every format the viewer opens: OME-Zarr, OME-TIFF, CZI, Phenix and Yokogawa plates, and slides from Aperio, Hamamatsu, Leica, Philips, 3DHISTECH, Akoya, DICOM."},"headers":[],"relativePath":"guides/supported-formats.md","filePath":"guides/supported-formats.md"}'),d={name:"guides/supported-formats.md"};function i(s,e,n,l,h,p){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="supported-formats" tabindex="-1">Supported Formats <a class="header-anchor" href="#supported-formats" aria-label="Permalink to &quot;Supported Formats&quot;">​</a></h1><p>Open the files your instruments write. OME-Zarr too. Here is what the viewer opens today. Nothing is converted or uploaded.</p><table tabindex="0"><thead><tr><th>Format</th><th>Kind</th><th>What you open</th><th>Views</th><th><a href="./local-files.html#zip-without-compression">Zip without compression</a></th></tr></thead><tbody><tr><td><a href="./ome-zarr.html">OME-Zarr</a></td><td>Microscopy</td><td>A folder, or its address</td><td>Images in 2D and 3D. Plates in Plate, Well and Field view</td><td>Yes, as one <code>.ozx</code> or <code>.zip</code> file</td></tr><tr><td><a href="./ome-tiff.html">OME-TIFF</a></td><td>Microscopy</td><td>One file</td><td>Images in 2D and 3D, with Z and T</td><td>Not needed</td></tr><tr><td><a href="./zeiss-czi.html">Zeiss CZI</a></td><td>Microscopy</td><td>One file, or a folder of one file per field</td><td>Images in 2D and 3D. Plates in Field view</td><td>Yes, one CZI per field</td></tr><tr><td><a href="./opera-phenix-plates.html">Opera Phenix / Harmony</a></td><td>Plates</td><td>The measurement folder</td><td>Field view</td><td>Yes, compressed or not</td></tr><tr><td><a href="./yokogawa-plates.html">Yokogawa CellVoyager</a></td><td>Plates</td><td>The measurement folder</td><td>Field view</td><td>Yes, compressed or not</td></tr><tr><td><a href="./aperio-svs.html">Aperio SVS</a></td><td>Pathology</td><td>One file</td><td>Slide in 2D</td><td>Not needed</td></tr><tr><td><a href="./hamamatsu-ndpi.html">Hamamatsu NDPI</a></td><td>Pathology</td><td>One file, also over 4 GB</td><td>Slide in 2D</td><td>Not needed</td></tr><tr><td><a href="./leica-scn.html">Leica SCN</a></td><td>Pathology</td><td>One file, every region</td><td>Slide in 2D</td><td>Not needed</td></tr><tr><td><a href="./philips-tiff.html">Philips TIFF</a></td><td>Pathology</td><td>One file</td><td>Slide in 2D</td><td>Not needed</td></tr><tr><td><a href="./akoya-qptiff.html">Akoya QPTIFF</a></td><td>Pathology</td><td>One file, or an inForm <code>.tif</code> export</td><td>Slide in 2D, brightfield or multiplex</td><td>Not needed</td></tr><tr><td><a href="./mrxs.html">3DHISTECH MRXS</a></td><td>Pathology</td><td>The <code>.mrxs</code> file with its folder</td><td>Slide in 2D</td><td>Yes</td></tr><tr><td><a href="./dicom-wsi.html">DICOM WSI</a></td><td>Pathology</td><td>A folder of <code>.dcm</code> files</td><td>Slide in 2D</td><td>Yes</td></tr></tbody></table><p>Each opens from your disk or by its address. A zip made without compression is one file, so it opens in every browser, from your disk or its address. Plate and Well view need the lower resolutions that OME-Zarr stores. The other plate formats keep each field at one resolution, so they open in Field view. <a href="https://www.find-nuclei.com/blog/how-to-convert-to-ome-zarr" target="_blank" rel="noreferrer">Convert a plate to OME-Zarr</a> for all three. Details and limits are on each format&#39;s page. Which formats state their pixel size and magnification, and how to set them when a file does not: <a href="./calibration.html">Pixel Size and Magnification</a>.</p><h2 id="companion-data" tabindex="-1">Companion data <a class="header-anchor" href="#companion-data" aria-label="Permalink to &quot;Companion data&quot;">​</a></h2><ul><li><strong>Label masks</strong> that live outside the image: a Zarr label array from a URL, or from a folder in Chrome and Edge. See <a href="./labels.html">Labels</a>.</li><li><strong>Measurements and analysis bundles:</strong> a CSV or Parquet table with one row per object, up to a run manifest that lists several masks and tables, all from one URL. A table also opens from your disk in Chrome and Edge. See <a href="./analytics-format.html">Analytics Data Format</a>, and <a href="https://www.find-nuclei.com/blog/hcs-analytics-in-the-browser" target="_blank" rel="noreferrer">HCS Analytics in the Browser</a> for a real screen.</li><li><strong>Plate manifests:</strong> a small JSON file that describes an Opera Phenix or Yokogawa CellVoyager plate. Save one from the viewer and open it by URL. The format is a published JSON Schema: <a href="https://find-nuclei.github.io/schemas/plate-manifest/v1.json" target="_blank" rel="noreferrer">plate-manifest/v1.json</a>.</li></ul><h2 id="which-browser-opens-what" tabindex="-1">Which browser opens what <a class="header-anchor" href="#which-browser-opens-what" aria-label="Permalink to &quot;Which browser opens what&quot;">​</a></h2><p>One file and every address open in every browser. A folder from your disk needs Chrome or Edge. The full table is in <a href="./local-files.html#which-browsers-can-do-this">Local Files</a>.</p><h2 id="not-supported-yet" tabindex="-1">Not supported yet <a class="header-anchor" href="#not-supported-yet" aria-label="Permalink to &quot;Not supported yet&quot;">​</a></h2><p>Other vendor formats open after conversion to OME-Zarr. <a href="https://www.find-nuclei.com/blog/how-to-convert-to-ome-zarr" target="_blank" rel="noreferrer">How to Convert Any Microscopy File to OME-Zarr</a> shows how.</p><p>Which format should we add next? Tell us at <a href="mailto:info@find-nuclei.com" target="_blank" rel="noreferrer">info@find-nuclei.com</a>.</p>',11)])])}const c=t(d,[["render",i]]);export{f as __pageData,c as default};
